sharedAndPointTypes:
// persisted-json-core.ts
interface PersistenceOptions {
  pathProfile: PythonPathProfile;
  intMaxStrDigits: number;
}
interface PersistenceText<T> {
  literal(ascii: string): T;
  concat(parts: readonly T[]): T;
}
interface PersistenceValueAdapter<V, T> {
  scalar(value: V): T | undefined;
  array(value: V): { identity: object; items: readonly V[] } | undefined;
  object(value: V): {
    identity: object;
    empty: boolean;
    // Invoked lazily AFTER the profile-specific initial yielded prefix.
    sortedEntries(): ReadonlyArray<{ key: T; readValue(): V }>;
  } | undefined;
  unsupported(value: V): never;
  circular(): never;
}
// persistence-exception.ts
interface ExceptionDescriptor {
  cause?: unknown;
  suppressContext?: boolean;
}
interface ExceptionFacts {
  name: string;
  message: string;
  errno: number | null;
  cause: unknown;       // null when absent; original object/value otherwise
  context: unknown;    // null when absent; actual prior thrown value otherwise
  suppressContext: boolean;
  unicode: null | {
    encoding: "utf-8";
    reason: "surrogates not allowed";
    object: object;     // opaque to shared code; point leaf validates PythonText
    start: number;
    end: number;
  };
}
type ContextLinker = (error: unknown, previous: unknown) => unknown;
interface PointAppendHistoryOptions {
  isIdempotent(event: PythonPointJson): Promise<boolean>;
  serialization: PersistenceOptions;
  io?: JsonlHistoryIO;
}
type PointAtomicWriteIO = AtomicWriteIOFor<PythonText>;
interface PointExceptionFacts extends Omit<ExceptionFacts, "unicode"> {
  unicode: null | {
    encoding: "utf-8";
    reason: "surrogates not allowed";
    object: PythonText;
    start: number;
    end: number;
  };
}
function pointExceptionFacts(error: Error): PointExceptionFacts;
function describePointException(error: Error, descriptor: ExceptionDescriptor): void;
